package de.corporate.lc.swift;
import org.junit.jupiter.api.Test; import java.time.LocalDate; import static org.assertj.core.api.Assertions.assertThat;
class Mt700ParserPrintedDateTest {@Test void parsesPrintedDatesWithAndWithoutSpacing(){String raw=":20:TEST-1\n:31C:16.06.2026\n:31D:15.09. 2026 GERMANY\n:32B:EUR 25.905,03\n:44C:25.08.2026\n:50:Applicant\n:59:Beneficiary";var lc=new Mt700Parser().parse(raw);assertThat(lc.getIssueDate()).isEqualTo(LocalDate.of(2026,6,16));assertThat(lc.getExpiryDate()).isEqualTo(LocalDate.of(2026,9,15));assertThat(lc.getExpiryPlace()).isEqualTo("GERMANY");assertThat(lc.getLatestShipmentDate()).isEqualTo(LocalDate.of(2026,8,25));assertThat(lc.getAmount()).isEqualByComparingTo("25905.03");}
@Test void parsesSwiftDatesAsYearMonthDay(){String raw=":20:TEST-2\n:31C:260616\n:31D:260915GERMANY\n:32B:EUR25905,03\n:44C:260825\n:50:Applicant\n:59:Beneficiary";var lc=new Mt700Parser().parse(raw);assertThat(lc.getIssueDate()).isEqualTo(LocalDate.of(2026,6,16));assertThat(lc.getExpiryDate()).isEqualTo(LocalDate.of(2026,9,15));assertThat(lc.getLatestShipmentDate()).isEqualTo(LocalDate.of(2026,8,25));}}
